-- ── Data backfill (existing records keep their behaviour) ─────────────────────
UPDATE "PayComponent" SET "category" = CASE WHEN "kind" = 'ALLOWANCE' THEN 'ALLOWANCE'::"ComponentCategory" ELSE 'DEDUCTION'::"ComponentCategory" END WHERE "category" IS NULL;
UPDATE "PayComponent" SET "netEffect" = 'DEDUCT', "employerCost" = false, "aovIncluded" = false WHERE "kind" = 'DEDUCTION';
-- Legacy AOV base was base + taxable allowances: only taxable allowances count towards it.
UPDATE "PayComponent" SET "aovIncluded" = false WHERE "kind" = 'ALLOWANCE' AND "taxTreatment" <> 'TAXABLE';

UPDATE "TaxRuleSet" SET "verificationStatus" = CASE WHEN "isVerified" THEN 'VERIFIED'::"LegalStatus" ELSE 'PENDING_VERIFICATION'::"LegalStatus" END;
UPDATE "PayrollRun" r SET "legalStatus" = CASE WHEN t."isVerified" THEN 'VALIDATED'::"RunLegalStatus" ELSE 'PENDING_LEGAL_VALIDATION'::"RunLegalStatus" END FROM "TaxRuleSet" t WHERE t."id" = r."taxRuleSetId";
UPDATE "Payslip" p SET "taxRuleSetId" = r."taxRuleSetId", "legalStatus" = r."legalStatus" FROM "PayrollRun" r WHERE r."id" = p."runId";

-- Leave types: categories and policy settings for the default codes.
UPDATE "LeaveType" SET "category" = 'ANNUAL', "componentCode" = 'LEV001', "carryForward" = false WHERE "code" = 'VAC';
UPDATE "LeaveType" SET "category" = 'SICK', "componentCode" = 'LEV002' WHERE "code" = 'SICK';
UPDATE "LeaveType" SET "category" = 'MATERNITY', "componentCode" = 'LEV007', "statutoryDays" = 80, "legalStatus" = 'PENDING_VERIFICATION', "legalReference" = 'Wet Arbeidsbescherming Gezin, S.B. 2019 no. 64 — 16 weken (24 bij meerlingen van 3+)' WHERE "code" = 'MAT';
UPDATE "LeaveType" SET "category" = 'PATERNITY', "componentCode" = 'LEV008', "statutoryDays" = 8, "legalStatus" = 'CONFLICT', "legalReference" = 'Wet Arbeidsbescherming Gezin, S.B. 2019 no. 64 — duur volgens bronnen 5, 7 of 8 dagen' WHERE "code" = 'PAT';
UPDATE "LeaveType" SET "category" = 'SPECIAL', "componentCode" = 'LEV003' WHERE "code" = 'CAL';
UPDATE "LeaveType" SET "category" = 'UNPAID', "componentCode" = 'LEV004', "payPercentBp" = 0, "legalStatus" = 'COMPANY_POLICY' WHERE "code" = 'UNP';

-- Parental leave types for every existing company (Dutch names; companies can rename).
SELECT 'lt_' || md5(c."id" || v.code), c."id", v.code, v.name, true, 0, v.cat::"LeaveCategory", v.comp, v.days, v.status::"LegalStatus", v.ref, v.pt, 10000
FROM "Company" c
CROSS JOIN (VALUES
  ('OUD', 'Ouderschapsverlof', 'PARENTAL', 'LEV006', NULL::double precision, 'COMPANY_POLICY', 'Geen afzonderlijke wettelijke regeling gevonden — bedrijfsbeleid', true),
  ('ADO', 'Adoptieverlof', 'ADOPTION', 'LEV009', 30::double precision, 'PENDING_VERIFICATION', 'Wet Arbeidsbescherming Gezin, S.B. 2019 no. 64 — 6 weken (kind < 18 maanden)', false),
  ('FEEST', 'Feestdagen', 'PUBLIC_HOLIDAY', 'LEV005', NULL::double precision, 'COMPANY_POLICY', NULL, false),
  ('AZT', 'Afwezigheid zonder toestemming', 'UNAUTHORIZED', 'LEV010', NULL::double precision, 'COMPANY_POLICY', NULL, false)
) AS v(code, name, cat, comp, days, status, ref, pt)
ON CONFLICT ("companyId", "code") DO NOTHING;
UPDATE "LeaveType" SET "payPercentBp" = 0, "isPaid" = false WHERE "code" = 'AZT';

