INSERT INTO "LegalSource" ("code","title","publication","publishedAt","effectiveFrom","subject","articles","url","verificationStatus","notes","updatedAt") VALUES ('SB-2022-149','Wet van 30 december 2022 houdende nadere wijziging van de Wet Loonbelasting','S.B. 2022 no. 149','2022-12-30',NULL,'Verwerking van de heffingskorting in de belastingvrije som','[{"article":"—","summary":"Heffingskorting opgenomen in de belastingvrije som (geen afzonderlijke heffingskorting meer)"}]'::jsonb,'https://www.sris.sr/wp-content/uploads/2023/01/S.B.-2022-no.-149-wijziging-van-de-Wet-Loonbelasting.pdf','PENDING_VERIFICATION','Inhoud alleen via secundaire samenvatting bevestigd; volledige tekst nalezen.',NOW()) ON CONFLICT ("code") DO NOTHING;
INSERT INTO "LegalSource" ("code","title","publication","publishedAt","effectiveFrom","subject","articles","url","verificationStatus","notes","updatedAt") VALUES ('SB-2024-2','Staatsbesluit ter uitvoering van artikel 18a van de Wet Loonbelasting','S.B. 2024 no. 2','2024-01-11','2024-01-01','Beroepskostenaftrek, belastingvrije som en tariefschijven loonbelasting','[{"article":"12","summary":"Beroepskostenaftrek SRD 4.800 per jaar (SRD 400 per maand)"},{"article":"13","summary":"Belastingvrije som SRD 108.000 per jaar (SRD 9.000 per maand)"},{"article":"14","summary":"Tarief: 8% tot SRD 42.000; 18% tot SRD 84.000; 28% tot SRD 126.000; 38% daarboven"},{"article":"17a lid 2","summary":"Afzonderlijke tariefstructuur: 5% / 15% / 25% / 35% (zelfde schijfgrenzen). Toepassingsbereik nog te verifiëren"}]'::jsonb,'https://www.sris.sr/wp-content/uploads/2024/01/S.B.-2024-no.-2-STAATSBESLUIT-11-januari-2024-uitvoeringartikel-18a-Wet-Loonbelasting-S.B.-1981-no.-181-laatstelijk-gewijzigd-S.B.pdf','PENDING_VERIFICATION','Primaire bron aangeleverd door ARA Intelligent Solutions. Nagaan of latere staatsbesluiten (o.a. S.B. 2025 no. 101 en no. 129) deze bepalingen hebben gewijzigd vóór productiegebruik in 2026.',NOW()) ON CONFLICT ("code") DO NOTHING;
INSERT INTO "LegalSource" ("code","title","publication","publishedAt","effectiveFrom","subject","articles","url","verificationStatus","notes","updatedAt") VALUES ('SB-2025-101','Staatsbesluit van 22 juli 2025 ter uitvoering van artikel 18a van de Wet Loonbelasting','S.B. 2025 no. 101','2025-07-22',NULL,'Vrijstelling bijzondere beloningen (SRD 10.016 → SRD 19.500 per jaar) en verbreding overwerkschijven (5% tot SRD 2.500; 15% tot SRD 7.500)','[{"article":"—","summary":"Volgens secundaire bronnen terugwerkend tot 1 jan. 2025 (bonus) resp. 1 juli 2025 (overwerk)"}]'::jsonb,'https://www.sris.sr/wp-content/uploads/2025/07/S.B.-2025-no.-101-STAATSBESLUIT-van-22-juli-2025-ter-uitvoering-van-artikel-18a-van-de-Wet-Loonbelasting.pdf','CONFLICT','Volgens S.B. 2025 no. 129 (29 okt. 2025) ingetrokken. Inhoud van no. 129 niet beschikbaar — professionele beoordeling vereist.',NOW()) ON CONFLICT ("code") DO NOTHING;
INSERT INTO "LegalSource" ("code","title","publication","publishedAt","effectiveFrom","subject","articles","url","verificationStatus","notes","updatedAt") VALUES ('SB-2025-129','Staatsbesluit ter uitvoering van artikel 18a van de Wet Loonbelasting','S.B. 2025 no. 129','2025-10-29',NULL,'Trekt S.B. 2025 no. 101 in; overige inhoud niet geverifieerd','[]'::jsonb,'https://www.sris.sr/wp-content/uploads/2025/11/S.B.-2025-no.-129-STAATSBESLUIT-ter-uitvoering-van-artikel-18a-van-de-Wet-Loonbelasting.pdf','CONFLICT',NULL,NOW()) ON CONFLICT ("code") DO NOTHING;
INSERT INTO "LegalSource" ("code","title","publication","publishedAt","effectiveFrom","subject","articles","url","verificationStatus","notes","updatedAt") VALUES ('WET-AOV','Wet Algemene Oudedagsvoorziening','Wet AOV (zoals gewijzigd)',NULL,NULL,'AOV-premie','[{"article":"—","summary":"Premie 4% van de heffingsgrondslag"},{"article":"—","summary":"Grondslag: zuiver inkomen (IB 1922) of, als loonbelasting verschuldigd is, het zuiver loon (Wet Loonbelasting)"},{"article":"—","summary":"Premieplichtig: ingezetene die de leeftijd van 60 jaar nog niet heeft bereikt; heffing o.a. door inhouding op het loon"}]'::jsonb,'https://belastingdienst.sr/wp-content/uploads/2024/10/Wet-AOV.pdf','PENDING_VERIFICATION','Geen franchise gevonden. Aangifte loonbelasting en premie AOV is één gecombineerde maandaangifte (online portaal sinds 2024).',NOW()) ON CONFLICT ("code") DO NOTHING;
INSERT INTO "LegalSource" ("code","title","publication","publishedAt","effectiveFrom","subject","articles","url","verificationStatus","notes","updatedAt") VALUES ('SB-2019-64','Wet Arbeidsbescherming Gezin (bescherming moederschap)','S.B. 2019 no. 64','2019-06-10',NULL,'Zwangerschaps- en bevallingsverlof, vaderschapsverlof, adoptieverlof','[{"article":"—","summary":"Zwangerschaps- en bevallingsverlof samen max. 16 weken (24 weken bij meerlingen van drie of meer); 4–6 weken vóór en 10–12 weken na de bevalling"},{"article":"—","summary":"Adoptie van een kind jonger dan 18 maanden: 6 weken betaald verlof voor de adoptiemoeder"},{"article":"—","summary":"Vaderschapsverlof: duur volgens bronnen 5, 7 of 8 dagen (conflict)"},{"article":"—","summary":"Loondoorbetaling via fonds (FVO); bijdrage volgens berichtgeving 1% van het brutoloon — niet geverifieerd"}]'::jsonb,'https://gov.sr/wp-content/uploads/2022/09/wet-arbeidsbescherming-gezin-bescherming-moederschap.pdf','PENDING_VERIFICATION',NULL,NOW()) ON CONFLICT ("code") DO NOTHING;
